/**
 *
 * OrganizationChartNodes iterates the org-chart data and calls its render function once per node,
 * preserving the 2D tree nesting (connectors) internally — no recursion in user code.
 *
 * [Live Demo](https://www.primereact.org/organizationchart/)
 *
 * @module OrganizationChartNodes
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { TreeNode } from '@primereact/types/headless/organizationchart';
import * as React from 'react';
import type { BaseComponentProps, PassThroughType } from '../..';
/**
 * Per-node payload passed to the `OrganizationChartNodes` render function.
 */
export interface OrganizationChartNodeRow {
    /**
     * The node data.
     */
    node: TreeNode;
    /**
     * Whether the node is expanded (not collapsed).
     */
    expanded: boolean;
    /**
     * Whether the node has no children.
     */
    leaf: boolean;
    /**
     * Whether the node is selected.
     */
    selected: boolean;
    /**
     * Whether the node is partially selected (checkbox mode).
     */
    partiallySelected: boolean;
    /**
     * Whether the node can be selected (a `selectionMode` is set).
     */
    selectable: boolean;
    /**
     * Whether the node can be expanded/collapsed (has children).
     */
    expandable: boolean;
    /**
     * 1-based depth of the node in the tree.
     */
    level: number;
}
/**
 * Defines passthrough(pt) options type in OrganizationChartNodes component.
 */
export type OrganizationChartNodesPassThroughType<E> = PassThroughType<OrganizationChartNodesInstance, E>;
/**
 * Defines passthrough(pt) options of OrganizationChartNodes component.
 */
export interface OrganizationChartNodesPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: OrganizationChartNodesPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in OrganizationChartNodes component.
 */
export interface OrganizationChartNodesProps extends BaseComponentProps<OrganizationChartNodesInstance, unknown, OrganizationChartNodesPassThrough> {
    /**
     * Render-prop. Called once per node with its row payload; must return the node UI.
     */
    children?: ((row: OrganizationChartNodeRow) => React.ReactNode) | React.ReactNode;
}
/**
 * Defines valid state in OrganizationChartNodes component.
 */
export interface OrganizationChartNodesState {
}
/**
 * Defines the methods and properties exposed by OrganizationChartNodes component.
 */
export interface OrganizationChartNodesExposes {
}
/**
 * Instance of OrganizationChartNodes component.
 */
export type OrganizationChartNodesInstance = ComponentInstance<OrganizationChartNodesProps, OrganizationChartNodesState, OrganizationChartNodesExposes>;
